use gearth_rust::{expression,packet::{Direction,Packet},packet_info::PacketInfoManager};
#[test] fn raw_display_notation_matches_original_for_all_bytes() {let mut p=Packet::new(123);p.append(&(0u8..=255).collect::<Vec<_>>()).unwrap();assert_eq!(expression::parse(&expression::wire_display(p.bytes())).unwrap().bytes(),p.bytes());}
#[test] fn named_headers_resolve_names_and_hashes_with_direction() {let db=PacketInfoManager::from_tsv("TEST","TOSERVER\t77\tChat\tabcd\ts\ttest\nTOCLIENT\t78\tChat\tdefg\ts\ttest\n").unwrap();assert_eq!(expression::parse_with_info("{out:Chat}{s:\"hello\"}",Direction::ToServer,&db).unwrap().header(),77);assert_eq!(expression::parse_with_info("{in:defg}{s:\"hello\"}",Direction::ToClient,&db).unwrap().header(),78);assert!(expression::parse_with_info("{in:Chat}",Direction::ToServer,&db).is_err());assert!(expression::parse("{out:Chat}").is_err());}
#[test] fn mixed_typed_and_raw_fields_and_signed_header() {let mut p=expression::parse("{h:-1}{b:True}[255]{s:\"é\"}").unwrap();assert_eq!(p.header(),65535);assert!(p.read_bool().unwrap());assert_eq!(p.read_u8().unwrap(),255);assert_eq!(p.read_string().unwrap(),"é");}
